"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["68713"],{79648(a){a.exports=JSON.parse('{"id":"F411","slug":"ewma-volatility","name":"EWMA Volatility (RiskMetrics)","subject":"Quantitative Finance","section":"Quant","topic":"GARCH volatility models","level":"Intermediate","aliases":["exponentially weighted moving average","RiskMetrics","decay factor","GARCH volatility models"],"formula":{"latex":"\\\\sigma_{t}^{2}=\\\\lambda\\\\,\\\\sigma_{t-1}^{2}+(1-\\\\lambda)\\\\,r_{t-1}^{2}","also":[],"text":"Variance today = lambda x yesterday\'s variance + (1 - lambda) x yesterday\'s return squared. RiskMetrics uses lambda = 0.94 for daily data"},"symbols":[{"symbol":"lambda","meaning":"Decay factor. Higher values mean a slower-moving estimate","unit":"number"},{"symbol":"r","meaning":"Daily return","unit":"percent"},{"symbol":"sigma^2","meaning":"Variance estimate","unit":"number"}],"when_to_use":"Use it for a quick volatility estimate that reacts to recent returns more than old ones. It is GARCH with omega = 0 and alpha + beta = 1, so it has no long-run level and its forecast is flat. It needs only one parameter, which is why risk systems used it as a default.","worked_example":{"problem":"The last ten daily returns, oldest first, are 0.4%, -1.2%, 0.8%, -2.5%, 1.1%, -0.3%, 0.6%, -1.8%, 2.2% and -0.9%. Use lambda = 0.94, starting from the first return squared.","inputs":{"r":[0.4,-1.2,0.8,-2.5,1.1,-0.3,0.6,-1.8,2.2,-0.9],"lam":0.94},"steps":[{"label":"EWMA variance (recursion, seeded with the first squared return)","working":null,"value":"0.00009967"},{"label":"Daily volatility","working":"sqrt(var)","value":"0.998%"},{"label":"Annualized (x sqrt 252)","working":"0.00998366 x sqrt(252)","value":"15.85%"},{"label":"Equal-weight daily volatility (root mean square)","working":null,"value":"1.380%"}],"answer":"The current daily variance is 0.00009967, a daily volatility of 0.998% or 15.85% annualized. A plain average of the ten returns would give 1.380%, so the EWMA is weighting recent days differently."},"calculator":{"available":true,"inputs":[{"id":"r","label":"Daily returns, oldest first","unit":"%","type":"list","default":[0.4,-1.2,0.8,-2.5,1.1,-0.3,0.6,-1.8,2.2,-0.9],"hint":""},{"id":"lam","label":"Decay factor lambda","unit":"","type":"number","default":0.94,"hint":"","min":0.5}],"checks":[{"expr":"count(r)>=2 and lam>0 and lam<1","message":"Enter at least two returns and a lambda between 0 and 1."}],"steps":[{"id":"var","label":"EWMA variance (recursion, seeded with the first squared return)","expr":"ewmavar(r, lam)","format":"num8"},{"id":"vol","label":"Daily volatility","expr":"sqrt(var)","format":"pct3"},{"id":"ann","label":"Annualized (x sqrt 252)","expr":"vol*sqrt(252)","format":"pct2"},{"id":"plain","label":"Equal-weight daily volatility (root mean square)","expr":"sqrt(mean(square(r)))","format":"pct3"}],"results":["vol","ann","plain"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"var":9.967345629697664e-5,"vol":0.00998365946419331,"ann":0.15848568069967114,"plain":1.3798550648528272e-2}},"finder":{"finds":"A volatility estimate that favors recent returns","needs":"A list of daily returns and a decay factor"},"related":[{"slug":"garch-forecast","name":"GARCH(1,1) Variance Forecast"},{"slug":"var-parametric","name":"Value at Risk: Parametric (Variance-Covariance)"}],"related_ids":["F412","F378"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msubsup><mi>\u03C3</mi><mi>t</mi><mn>2</mn></msubsup><mo>=</mo><mi>\u03BB</mi><mtext>\u2009</mtext><msubsup><mi>\u03C3</mi><mrow><mi>t</mi><mo>\u2212</mo><mn>1</mn></mrow><mn>2</mn></msubsup><mo>+</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>\u03BB</mi><mo stretchy=\\"false\\">)</mo><mtext>\u2009</mtext><msubsup><mi>r</mi><mrow><mi>t</mi><mo>\u2212</mo><mn>1</mn></mrow><mn>2</mn></msubsup></mrow><annotation encoding=\\"application/x-tex\\">\\\\sigma_{t}^{2}=\\\\lambda\\\\,\\\\sigma_{t-1}^{2}+(1-\\\\lambda)\\\\,r_{t-1}^{2}</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><msubsup><mi>\u03C3</mi><mi>t</mi><mn>2</mn></msubsup></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\sigma_{t}^{2}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>\u03BB</mi><mtext>\u2009</mtext><msubsup><mi>\u03C3</mi><mrow><mi>t</mi><mo>\u2212</mo><mn>1</mn></mrow><mn>2</mn></msubsup><mo>+</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>\u03BB</mi><mo stretchy=\\"false\\">)</mo><mtext>\u2009</mtext><msubsup><mi>r</mi><mrow><mi>t</mi><mo>\u2212</mo><mn>1</mn></mrow><mn>2</mn></msubsup></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\lambda\\\\,\\\\sigma_{t-1}^{2}+(1-\\\\lambda)\\\\,r_{t-1}^{2}</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"event-study-car","name":"Event Study: Abnormal and Cumulative Abnormal Return"},"next":{"slug":"ex-dividend-price","name":"Ex-Dividend Price Drop"},"lesson":null,"total":522}')}}]);